"""Detection-limits suite for scanner v2. Cases are written by the authors, with a truth label and a prediction fixed BEFORE the scanner is run on them.
truth: "defect" = the pattern as defined in main.tex Section 1 is present and could change a result; "benign" = the code shows the syntax the rule looks for but is harmless, or is clean.
kind: canonical (the form the rule was written for), variant (same defect, different spelling), lookalike (benign code that resembles the pattern), clean.
pred: my prediction, from reading the scanner source, of whether the named rule fires on the case."""
LE = "from sklearn.preprocessing import LabelEncoder\n"
C = []
def add(i, rule, truth, kind, pred, src): C.append(dict(id=i, rule=rule, truth=truth, kind=kind, pred=pred, src=src))

# ENC_PER_FRAME (inconsistent category codes across frames)
add("E1","ENC_PER_FRAME","defect","canonical",True, LE+"def encode(df):\n    for c in ['sex','race']:\n        df[c] = LabelEncoder().fit_transform(df[c])\n    return df\n")
add("E2","ENC_PER_FRAME","defect","canonical",True, LE+"def encode(df):\n    out = df.copy()\n    for c in ['sex']:\n        le = LabelEncoder()\n        out[c] = le.fit_transform(out[c])\n    return out\n")
add("E3","ENC_PER_FRAME","defect","variant",False, "from sklearn.preprocessing import LabelEncoder as LE\ndef encode(df):\n    df['a'] = LE().fit_transform(df['a'])\n    return df\n")
add("E4","ENC_PER_FRAME","defect","variant",False, "from sklearn.preprocessing import OrdinalEncoder\ndef encode(df):\n    df[['a','b']] = OrdinalEncoder().fit_transform(df[['a','b']])\n    return df\n")
add("E5","ENC_PER_FRAME","defect","variant",False, "import pandas as pd\ndef encode(df):\n    df['a'] = pd.factorize(df['a'])[0]\n    return df\n")
add("E6","ENC_PER_FRAME","defect","variant",False, "def encode(df):\n    df['a'] = df['a'].astype('category').cat.codes\n    return df\n")
add("E7","ENC_PER_FRAME","defect","variant",False, LE+"def encode(df, encoder_kind='label'):\n    df['a'] = LabelEncoder().fit_transform(df['a'])\n    return df\n")
add("E8","ENC_PER_FRAME","benign","lookalike",False, LE+"def encode(train, test):\n    le = LabelEncoder().fit(train['a'])\n    return le.transform(train['a']), le.transform(test['a'])\n")
add("E9","ENC_PER_FRAME","benign","lookalike",True, LE+"import pandas as pd\ndef run():\n    df = pd.read_csv('one_table.csv')\n    df['a'] = LabelEncoder().fit_transform(df['a'])\n    return df\n")
add("E10","ENC_PER_FRAME","benign","clean",False, "import pandas as pd\ndf = pd.read_csv('a.csv')\nprint(df.shape)\n")

# DROPNA_UNSCOPED (P6)
add("D1","DROPNA_UNSCOPED","defect","canonical",True, "import pandas as pd\ndf = pd.read_csv('a.csv')\ndf = df.dropna()\nx = df[['age','sex']]\n")
add("D2","DROPNA_UNSCOPED","defect","canonical",True, "def prep(members, holdout):\n    members = members.dropna()\n    return members, holdout\n")
add("D3","DROPNA_UNSCOPED","defect","canonical",True, "df = df.dropna(how='any')\nx = df[['age']]\n")
add("D4","DROPNA_UNSCOPED","defect","canonical",True, "df.dropna(inplace=True)\nx = df[['age']]\n")
add("D5","DROPNA_UNSCOPED","defect","variant",False, "import pandas as pd\ndf = pd.DataFrame.dropna(df)\nx = df[['age']]\n")
add("D6","DROPNA_UNSCOPED","defect","variant",False, "df = df.dropna(0)\nx = df[['age']]\n")
add("D7","DROPNA_UNSCOPED","defect","canonical",True, "df = df.dropna(thresh=2)\nx = df[['age']]\n")
add("D8","DROPNA_UNSCOPED","benign","lookalike",False, "def levels(df, col):\n    return df[col].dropna().unique()\n")
add("D9","DROPNA_UNSCOPED","benign","lookalike",True, "def clean(df, col):\n    s = df[col].dropna()\n    return s\n")
add("D10","DROPNA_UNSCOPED","benign","clean",False, "df = df.dropna(subset=['age'])\n")
add("D11","DROPNA_UNSCOPED","benign","lookalike",True, "def prep(df):\n    sub = df[['a','b']]\n    sub = sub.dropna()\n    return sub\n")
add("D12","DROPNA_UNSCOPED","benign","lookalike",False, "df = df.dropna(axis=1)\n")

# ROW_CAP (P2)
add("R1","ROW_CAP","defect","canonical",True, "import pandas as pd\ndf = pd.read_csv('labevents.csv', nrows=50000)\n")
add("R2","ROW_CAP","defect","canonical",True, "import pandas as pd\ndf = pd.read_table('x.tsv', nrows=1000)\n")
add("R3","ROW_CAP","defect","canonical",True, "q = 'SELECT * FROM labevents LIMIT 50000'\n")
add("R4","ROW_CAP","defect","variant",False, "import pandas as pd\ndf = pd.read_csv('a.csv').head(50000)\n")
add("R5","ROW_CAP","defect","variant",False, "import pandas as pd\ndf = pd.read_csv('a.csv')[:50000]\n")
add("R6","ROW_CAP","defect","variant",False, "import pandas as pd\ndf = next(pd.read_csv('a.csv', chunksize=50000))\n")
add("R7","ROW_CAP","defect","canonical",True, "import pandas as pd\nN = 50000\ndf = pd.read_csv('a.csv', nrows=N)\n")
add("R8","ROW_CAP","benign","lookalike",True, "import pandas as pd\ndef load(path, nrows=None):\n    return pd.read_csv(path, nrows=nrows)\n")
add("R9","ROW_CAP","benign","lookalike",True, "print(run_query('SELECT * FROM t LIMIT 5'))\n")
add("R10","ROW_CAP","benign","clean",False, "import pandas as pd\ndf = pd.read_csv('a.csv')\n")

# DEAD_MERGE (P3)
add("M1","DEAD_MERGE","defect","canonical",True, "def f(a, b):\n    m = a.merge(b, on='k')\n    return a\n")
add("M2","DEAD_MERGE","defect","canonical",True, "import pandas as pd\ndef f(a, b):\n    m = pd.merge(a, b, on='k')\n    return a\n")
add("M3","DEAD_MERGE","defect","variant",False, "def f(a, b):\n    m = a.join(b, on='k')\n    return a\n")
add("M4","DEAD_MERGE","defect","variant",False, "def f(a, b):\n    m = a.merge(b, on='k')\n    print(m.shape)\n    return a\n")
add("M5","DEAD_MERGE","defect","variant",False, "def f(a, b):\n    a.merge(b, on='k')\n    return a\n")
add("M6","DEAD_MERGE","defect","variant",False, "def f(a, b, c):\n    m = a.merge(b, on='k')\n    m = a.merge(c, on='k')\n    return m\n")
add("M7","DEAD_MERGE","benign","lookalike",False, "def f(a, b):\n    m = a.merge(b, on='k')\n    return m\n")
add("M8","DEAD_MERGE","benign","lookalike",False, "def f(a, b):\n    m = a.merge(b, on='k')\n    out = m[['x']]\n    return out\n")
add("M9","DEAD_MERGE","benign","lookalike",False, "class T:\n    def f(self, a, b):\n        self.merged = a.merge(b, on='k')\n")

# POS_SELECT (P1)
add("S1","POS_SELECT","defect","canonical",True, "def f(df):\n    return df.groupby('pid').first()\n")
add("S2","POS_SELECT","defect","canonical",True, "def f(df):\n    return df.drop_duplicates(subset='pid')\n")
add("S3","POS_SELECT","defect","canonical",True, "def f(df):\n    return df.iloc[0]\n")
add("S4","POS_SELECT","defect","variant",False, "def f(df):\n    return df.groupby('pid').last()\n")
add("S5","POS_SELECT","defect","variant",False, "def f(df):\n    return df.groupby('pid').head(1)\n")
add("S6","POS_SELECT","defect","variant",False, "def f(df):\n    return df.groupby('pid').nth(0)\n")
add("S7","POS_SELECT","defect","variant",False, "def f(df):\n    return df.groupby('pid').agg('first')\n")
add("S8","POS_SELECT","defect","variant",False, "import pandas as pd\ndef f(df):\n    return pd.pivot_table(df, index='pid', aggfunc='first')\n")
add("S9","POS_SELECT","benign","lookalike",False, "def f(df):\n    df = df.sort_values('t')\n    return df.groupby('pid').first()\n")
add("S10","POS_SELECT","benign","lookalike",True, "def f(df):\n    return df.drop_duplicates()\n")
add("S11","POS_SELECT","benign","lookalike",True, "def f(df):\n    total = df.agg({'x': 'sum'})\n    return total.iloc[0]\n")

